def timeRequiredToBuy(tickets, k):
    time = 0
    n = len(tickets)
    for i in range(n):
        # For persons before or at k: min(tickets[i], tickets[k])
        # For persons after k: min(tickets[i], tickets[k] - 1)
        if i <= k:
            time += min(tickets[i], tickets[k])
        else:
            time += min(tickets[i], tickets[k] - 1)
    return time
